WITH "per" AS (SELECT "t0"."customer_id" AS "customer_id", COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN 1 END) AS "orders" FROM "sales"."orders" AS "t0" WHERE ("t0"."status" = 'DONE') AND ("t0"."customer_id" IS NOT NULL) AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t0"."customer_id") SELECT CASE WHEN "per"."orders" < 2 THEN '0-1' WHEN "per"."orders" < 5 THEN '2-4' WHEN "per"."orders" >= 5 THEN '5+' END AS "orders_range", COUNT(*) AS "customers" FROM "per" GROUP BY CASE WHEN "per"."orders" < 2 THEN '0-1' WHEN "per"."orders" < 5 THEN '2-4' WHEN "per"."orders" >= 5 THEN '5+' END ORDER BY MIN("per"."orders") ASC LIMIT 1000
